"""Factual pools: Biology, Agric. Topics = WAEC syllabus (waecsyllabus.com) + JAMB syllabus (ibass.jamb.gov.ng)."""
import random
from core import mk, uniq_pool

def _facts_pool(year, seed, facts):
    rng = random.Random(f"{seed}-{year}")
    P = []
    for q, c, ds, e, t in facts:
        ds2 = list(ds); rng.shuffle(ds2)
        P.append(mk(q, c, ds2, e, year, t))
    return uniq_pool(P)

